import{_ as s,a0 as o,w as d,s as a,ao as i,I as u,x as p,a1 as t,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"在ubuntu14.04上配置SNMPv3 | LCTT x X-CMD","titleTemplate":false,"description":"在ubuntu14.04上配置SNMPv3 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在ubuntu14.04上配置SNMPv3 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在ubuntu14.04上配置SNMPv3 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/How to configure SNMPv3 on ubuntu 14.04 server","title":"在ubuntu14.04上配置SNMPv3","tag":"201410","desc":""},"relativePath":"201410/How to configure SNMPv3 on ubuntu 14.04 server.md","filePath":"[post].md"}'),l={name:"201410/How to configure SNMPv3 on ubuntu 14.04 server.md"};function m(P,e,v,S,N,c){const n=o("Link");return d(),a("div",null,[e[11]||(e[11]=i(`<h1 id="在ubuntu14-04上配置snmpv3" tabindex="-1">在ubuntu14.04上配置SNMPv3 <a class="header-anchor" href="#在ubuntu14-04上配置snmpv3" aria-label="Permalink to “在ubuntu14.04上配置SNMPv3”">​</a></h1><p>簡單網絡管理協議（SNMP）是用於IP網絡設備管理的標準協議。典型的支持SNMP協議的設備有路由器、交換機、服務器、工作站、打印機及數據機櫃等等。SNMP一般被網絡管理系統用於按照管理員設定的條件來監視網絡附加設備。SNMP是因特網協議套件中的一個組成部分，它由IETF機構定義。它包含一系列的網絡管理標準，其中有一個應用層協議，一個數據庫架構以及一組數據對象。</p><p>SNMP將管理數據以變量的形式展示出來，這些變量描述了系統配置。同時這些變量可以被用於管理的應用查詢（或者被設置）。</p><h3 id="為什麼需要使用snmpv3" tabindex="-1">為什麼需要使用SNMPv3 <a class="header-anchor" href="#為什麼需要使用snmpv3" aria-label="Permalink to “為什麼需要使用SNMPv3”">​</a></h3><p>儘管SNMPv3所增加的加密功能並不影響協議層面，但是新的文本慣例、概念及術語使得它看起來很不一樣。</p><p>SNMPv3在SNMP的基礎之上增強了安全性以及遠程配置功能。</p><p>最初，SNMP最大的缺點就是安全性弱。SNMP的第一與第二個版本中，身份驗證僅僅是在管理員與代理間傳送一個明文的密碼而已。目前每一個SNMPv3的信息都包含了被編碼成8進制的安全參數。這些安全參數的具體意義由所選用的安全模型決定。</p><p>SNMPv3提供了重要的安全特性：</p><ul><li><p>保密性 —— 加密數據包以防止未經授權的源監聽。</p></li><li><p>完整性 —— 數據的完整性特性確保數據在傳輸的時候沒有被幹擾，並且包含了可選的數據響應保護機制。</p></li><li><p>身份驗證 —— 檢查數據是否來自一個合法的源。</p></li></ul><h3 id="在ubuntu中安裝snmp服務器及客户端" tabindex="-1">在ubuntu中安裝SNMP服務器及客户端 <a class="header-anchor" href="#在ubuntu中安裝snmp服務器及客户端" aria-label="Permalink to “在ubuntu中安裝SNMP服務器及客户端”">​</a></h3><p>打開終端運行下列命令</p><pre><code>sudo apt-get install snmpd snmp
</code></pre><p>安裝完成後需要做如下改變。</p><p>###配置SNMPv3###</p><p>獲得從外部守護進程訪問的權限</p><p>默認的安裝僅提供本地的訪問權限，如果想要獲得外部訪問權限，打開文件 /etc/default/snmpd。</p><pre><code>sudo vi /etc/default/snmpd
</code></pre><p>改變下列內容</p><p>將</p><pre><code>SNMPDOPTS=&#39;-Lsd -Lf /dev/null -u snmp -g snmp -I -smux,mteTrigger,mteTriggerConf -p /var/run/snmpd.pid&#39;
</code></pre><p>改為</p><pre><code>SNMPDOPTS=&#39;-Lsd -Lf /dev/null -u snmp -I -smux -p /var/run/snmpd.pid -c /etc/snmp/snmpd.conf&#39;
</code></pre><p>最後重啓 snmpd</p><pre><code>sudo /etc/init.d/snmpd restart
</code></pre><p>###定義 SNMPv3 用户，身份驗證以及加密參數 ###</p><p>“securityLevel”參數使得SNMPv3有多種不同的用途。</p><ul><li><p>noAuthNoPriv —— 沒有授權，加密以及任何安全保護！</p></li><li><p>authNoPriv —— 需要身份認證，但是不對通過網絡發送的數據進行加密。</p></li><li><p>autoPriv —— 最可靠模式。需要身份認證而且數據會被加密。</p></li></ul><p>snmpd 的配置以及設置都保存在文件 /etc/snmp/snmpd.conf。使用編輯器編輯文件：</p><pre><code>sudo vi /etc/snmp/snmpd.conf
</code></pre><p>在文件末尾添加以下內容：</p><pre><code>#
createUser user1
createUser user2 MD5 user2password
createUser user3 MD5 user3password DES user3encryption
#
rouser user1 noauth 1.3.6.1.2.1.1
rouser user2 auth 1.3.6.1.2.1
rwuser user3 priv 1.3.6.1.2.1
</code></pre><p>注：如果你需要使用自己的用户名/密碼對的話，請注意密碼及加密短語的最小長度是8個字符。</p><p>同時，你需要做如下的配置以便snmp可以監聽來自任何接口的連接請求。</p><p>將</p><pre><code>#agentAddress udp:161,udp6:[::1]:161
</code></pre><p>改為</p><pre><code>agentAddress udp:161,udp6:[::1]:161
</code></pre><p>保存改變後的snmpd.conf文件並且重啓守護進程：</p><pre><code>sudo /etc/init.d/snmpd restart
</code></pre><hr>`,40)),u("p",null,[e[1]||(e[1]=p("via: ",-1)),t(n,{href:"http://www.ubuntugeek.com/how-to-configure-snmpv3-on-ubuntu-14-04-server.html"},{default:r(()=>[...e[0]||(e[0]=[p("http://www.ubuntugeek.com/how-to-configure-snmpv3-on-ubuntu-14-04-server.html",-1)])]),_:1})]),u("p",null,[e[4]||(e[4]=p("譯者：",-1)),t(n,{href:"https://github.com/SPccman"},{default:r(()=>[...e[2]||(e[2]=[p("SPccman",-1)])]),_:1}),e[5]||(e[5]=p(" 校對：",-1)),t(n,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...e[3]||(e[3]=[p("Caroline",-1)])]),_:1})]),u("p",null,[e[8]||(e[8]=p("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[6]||(e[6]=[p("LCTT",-1)])]),_:1}),e[9]||(e[9]=p(" 原創翻譯，",-1)),t(n,{href:"http://linux.cn/"},{default:r(()=>[...e[7]||(e[7]=[p("Linux中國",-1)])]),_:1}),e[10]||(e[10]=p(" 榮譽推出",-1))])])}const T=s(l,[["render",m]]);export{b as __pageData,T as default};
